```json
{
  "root_causes": [
    {
      "service": "search",
      "fault_kind": "http_slow",
      "evidence": [
        {
          "kind": "trace",
          "sql": "WITH j AS (SELECT s.duration/1e6 cms, c.duration/1e6 sms, (epoch_ns(c.time)-epoch_ns(s.time))/1e6 start_gap_ms, ((epoch_ns(s.time)+s.duration)-(epoch_ns(c.time)+c.duration))/1e6 end_gap_ms FROM abnormal_traces s JOIN abnormal_traces c ON s.span_id=c.parent_span_id AND s.trace_id=c.trace_id WHERE s.service_name='search' AND c.service_name='rate') SELECT count(*) n, approx_quantile(cms,0.5) client_med_ms, approx_quantile(sms,0.5) rate_server_med_ms, approx_quantile(start_gap_ms,0.5) gap_before_server_med_ms, approx_quantile(end_gap_ms,0.5) gap_after_server_med_ms FROM j",
          "claim": "search's GetRates client spans take about 1640 ms median while rate's server spans take under 1 ms; the wait is before the server starts."
        },
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_span_kind, count(*) n, approx_quantile(duration/1e6, 0.95) p95_ms FROM abnormal_traces WHERE service_name='search' AND span_name IN ('geo.Geo/Nearby','rate.Rate/GetRates') AND attr_span_kind='Client' GROUP BY 1,2,3",
          "claim": "Only search's outgoing call to rate is slow (p95 about 2950 ms); search's call to geo stays at about 0.6 ms."
        },
        {
          "kind": "metric",
          "sql": "SELECT metric, service_name, attr_k8s_pod_name, max(value) mx, min(value) mn FROM abnormal_metrics WHERE metric IN ('k8s.container.restarts','k8s.pod.uptime') AND service_name IN ('search','rate') GROUP BY 1,2,3",
          "claim": "search and rate show no new restarts or uptime resets, and their CPU and memory stay low, so this is not a pod or resource fault."
        }
      ]
    }
  ],
  "propagation": [
    {
      "from": "search",
      "to": "frontend",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_span_kind, count(*) n, approx_quantile(duration/1e6, 0.95) p95_ms FROM abnormal_traces WHERE (service_name='frontend' AND span_name IN ('HTTP /hotels','search.Search/Nearby')) OR (service_name='search' AND span_name='search.Search/Nearby') GROUP BY 1,2,3",
          "claim": "frontend's /hotels server spans (p95 about 2950 ms) and its search client spans match search's Nearby server spans, so the delay passes straight through."
        }
      ]
    }
  ]
}
```

